import json, sys

data = json.loads(json.loads(sys.stdin.read())['result'])
exps = data['data']['experiments']

# Filter SmolVLA experiments for Table 1
# Table 1: Spatial, Goal, Object, Long × VLA-only, CRM K2mean, Adaptive × s42/43/44
results = []
for eid, exp in exps.items():
    spec = exp.get('spec', {}) or {}
    model = spec.get('model_name', '')
    conclusion = exp.get('conclusion', '')
    metrics = exp.get('metrics', {}) or {}
    sr = metrics.get('success_rate', metrics.get('overall_success_rate', None))
    server = spec.get('server', '')
    seed = spec.get('seed', '')
    command = spec.get('command', '')
    updated = exp.get('updated_at', '')

    # Only SmolVLA
    if 'smolvla' not in str(model).lower() and 'smolvla' not in command.lower() and 'pi05' not in eid.lower():
        # Check if it's a smolvla experiment by other indicators
        if '--model smolvla' not in command and 'smolvla' not in eid.lower():
            if '--model pi05' in command or 'pi05' in eid.lower():
                continue  # Skip pi05
            # Check if model field suggests smolvla
            pass

    if 'pi05' in eid.lower() or '--model pi05' in command:
        continue

    # Get benchmark
    benchmark = ''
    if '--benchmark' in command:
        parts = command.split('--benchmark')
        if len(parts) > 1:
            benchmark = parts[1].strip().split()[0].lower()
    elif 'spatial' in eid.lower():
        benchmark = 'spatial'
    elif 'goal' in eid.lower():
        benchmark = 'goal'
    elif 'object' in eid.lower():
        benchmark = 'object'
    elif 'long' in eid.lower():
        benchmark = 'long'

    # Get mode
    mode = ''
    if '--mode' in command:
        parts = command.split('--mode')
        if len(parts) > 1:
            mode = parts[1].strip().split()[0]
    elif 'vla_only' in eid.lower() or 'vla-only' in eid.lower():
        mode = 'vla_only'
    elif 'adaptive' in eid.lower() or 'adapt' in eid.lower():
        mode = 'adaptive_conformal_crm'
    elif 'crm' in eid.lower() or 'k2' in eid.lower():
        mode = 'crm_obs_only'

    if benchmark in ['spatial', 'goal', 'object', 'long'] and sr is not None:
        results.append({
            'exp_id': eid,
            'benchmark': benchmark,
            'mode': mode,
            'seed': seed,
            'sr': sr,
            'server': server,
            'conclusion': conclusion,
            'updated_at': updated[:10] if updated else '',
        })

# Sort by benchmark, mode, seed
results.sort(key=lambda x: (x['benchmark'], x['mode'], str(x['seed'])))

# Print as table
print(f'Total SmolVLA DONE experiments with SR: {len(results)}')
print()
for b in ['spatial', 'goal', 'object', 'long']:
    print(f'=== {b.upper()} ===')
    for r in results:
